        result["historical_failed_core_evidence_unchanged"]=True
        result["historical_failed_core_guarded_file_count"]=len(failed_evidence)
        result["historical56_web_receipts_unchanged"]=True
        result["prior_source_unchanged"]=True
        result["originals_unchanged"]=True
        result["source_unchanged"]=True
        result["base_source_unchanged"]=True
        result["written_files_unchanged"]=True
